def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find straight runs of matching markers separated by one background cell;
    # color the intervening cells when the run contains at least four markers.
    for dr, dc in ((0, 1), (1, 0), (1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == 6:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                points = [(r, c)]
                rr, cc = r, c
                while 0 <= rr + 2*dr < h and 0 <= cc + 2*dc < w:
                    rr += 2*dr
                    cc += 2*dc
                    if grid[rr][cc] != color:
                        break
                    points.append((rr, cc))
                if len(points) >= 4:
                    for (r1, c1), (r2, c2) in zip(points, points[1:]):
                        out[r1 + dr][c1 + dc] = 2
    return out
