    h, w = len(grid), len(grid[0])

    # Only horizontal alternating runs are transformed. Fill the background
    # gaps in long runs of the same non-background color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 6:
                continue
            if c >= 2 and grid[r][c - 2] == color and grid[r][c - 1] == 6:
                continue
            positions = [c]
            x = c
            while x + 2 < w and grid[r][x + 1] == 6 and grid[r][x + 2] == color:
                x += 2
                positions.append(x)
            if len(positions) >= 5:
                for x in positions[:-1]:
                    out[r][x + 1] = 2
    return out
